"a-drawn-timeline-of-the-nations-the-qu": "<svg viewBox=\"13.4 -2.6 736.8 325.5\" class=\"figsvg\" xmlns=\"http://www.w3.org/2000/svg\"><style>.figsvg text{text-anchor:middle;font-family:'NoorCard',system-ui,sans-serif}\n.figsvg .fl{font-size:21.0px;font-weight:700;fill:#FFFEF7}\n.figsvg .fs{font-size:17.0px;fill:rgba(255,254,247,0.904)}\n.figsvg .fk{font-size:16.0px;font-weight:700;fill:rgba(244,212,106,0.82)}\n.figsvg .fn{font-size:13.0px;font-weight:700;fill:rgba(255,254,247,0.703)}\n.figsvg .fd{font-size:15.0px;font-weight:700;fill:rgba(255,254,247,0.529);letter-spacing:.14em;text-transform:uppercase}\n.figsvg .s1{fill:none;stroke:#E9C86A;stroke-width:4.67;stroke-linecap:round;stroke-linejoin:round}\n.figsvg .s2{fill:none;stroke:rgba(255,254,247,0.904);stroke-width:3.59;stroke-linecap:round;stroke-linejoin:round}\n.figsvg .s3{fill:none;stroke:rgba(244,212,106,0.556);stroke-width:2.87;stroke-linecap:round;stroke-linejoin:round}\n.figsvg .f2{fill:#F4D46A;stroke:none}\n.figsvg .halo{fill:rgba(244,212,106,0.288);stroke:none}\n.figsvg .beam{fill:rgba(244,212,106,0.234);stroke:none}\n.figsvg .colglow{fill:rgba(244,212,106,0.221);stroke:none}\n.figsvg text.fl, .figsvg text.fs, .figsvg text.fk{paint-order:stroke}\n.figsvg .tl text.fl, .figsvg .tl text.fs, .figsvg .tl text.fk{text-anchor:middle}\n.figsvg .fl, .figsvg .fs, .figsvg .fk, .figsvg .fn, .figsvg .fd{stroke:none}\n.figsvg #sec-angels .figsvg text{text-anchor:start}</style>\n<title id=\"fig-peo-t\">A drawn timeline of the nations the Qur’an names, each with the sign it was given and the ending that followed refusal</title><path class=\"s1\" d=\"M46 160 H 706\"/><path class=\"s3\" d=\"M86 160 V 114\"/><circle class=\"f2\" cx=\"86\" cy=\"114\" r=\"7\"/><text class=\"fl\" x=\"86\" y=\"67\">The people</text><text class=\"fl\" x=\"86\" y=\"94\">of Nuh</text><text class=\"fs\" x=\"86\" y=\"43\">the ark on dry land</text><text class=\"fk\" x=\"86\" y=\"19\">the flood</text><path class=\"s3\" d=\"M204 160 V 206\"/><circle class=\"f2\" cx=\"204\" cy=\"206\" r=\"7\"/><text class=\"fl\" x=\"204\" y=\"230\">’Ad</text><text class=\"fs\" x=\"204\" y=\"261\">a cloud taken for rain</text><text class=\"fk\" x=\"204\" y=\"285\">the wind, seven nights</text><path class=\"s3\" d=\"M322 160 V 114\"/><circle class=\"f2\" cx=\"322\" cy=\"114\" r=\"7\"/><text class=\"fl\" x=\"322\" y=\"94\">Thamud</text><text class=\"fs\" x=\"322\" y=\"70\">the she-camel</text><text class=\"fk\" x=\"322\" y=\"46\">the cry at morning</text><path class=\"s3\" d=\"M440 160 V 206\"/><circle class=\"f2\" cx=\"440\" cy=\"206\" r=\"7\"/><text class=\"fl\" x=\"440\" y=\"230\">The people</text><text class=\"fl\" x=\"440\" y=\"257\">of Lut</text><text class=\"fs\" x=\"440\" y=\"288\">guests, and a deadline</text><text class=\"fk\" x=\"440\" y=\"312\">the cities overturned</text><path class=\"s3\" d=\"M558 160 V 114\"/><circle class=\"f2\" cx=\"558\" cy=\"114\" r=\"7\"/><text class=\"fl\" x=\"558\" y=\"94\">Madyan</text><text class=\"fs\" x=\"558\" y=\"70\">give the full measure</text><text class=\"fk\" x=\"558\" y=\"46\">the earthquake</text><path class=\"s3\" d=\"M676 160 V 206\"/><circle class=\"f2\" cx=\"676\" cy=\"206\" r=\"7\"/><text class=\"fl\" x=\"676\" y=\"230\">Pharaoh</text><text class=\"fs\" x=\"676\" y=\"261\">nine clear signs</text><text class=\"fk\" x=\"676\" y=\"285\">the sea closed</text></svg>",
