"a-money-flow-diagram-money-comes-in-is": "<svg viewBox=\"4.0 34.0 632.0 174.8\" class=\"figsvg\" xmlns=\"http://www.w3.org/2000/svg\"><style>.figsvg .ax, .figsvg .arw{fill:none;stroke:rgba(244,212,106,0.9);stroke-width:4.00}\n.figsvg .head{fill:rgba(244,212,106,0.95)}\n.figsvg .box{fill:rgba(255,254,247,0.167);stroke:rgba(244,212,106,0.837);stroke-width:3.64}\n.figsvg .box.hi{fill:rgba(244,212,106,0.301);stroke:rgba(244,212,106,0.9)}\n.figsvg .fh{fill:#F4D46A;font-size:14.0px;font-weight:800;letter-spacing:.06em;font-family:'NoorCard',system-ui,sans-serif}\n.figsvg .ft{fill:rgba(255,254,247,0.74);font-size:12.5px;font-family:'NoorCard',system-ui,sans-serif}</style>\n<title id=\"figB-t\">A money flow diagram: money comes in, is recorded by two people, goes out with receipts, and is announced to the community every month, while the book stays open</title>\n<rect class=\"box\" x=\"10\" y=\"40\" width=\"134\" height=\"76\" rx=\"10\"/>\n<text class=\"fh\" x=\"77\" y=\"68\" text-anchor=\"middle\">IN</text>\n<text class=\"ft\" x=\"77\" y=\"90\" text-anchor=\"middle\">what was given,</text>\n<text class=\"ft\" x=\"77\" y=\"106\" text-anchor=\"middle\">counted by two</text>\n<line class=\"arw\" x1=\"146\" y1=\"78\" x2=\"158\" y2=\"78\"/>\n<polygon class=\"head\" points=\"170,78 157,72 157,84\"/>\n<rect class=\"box\" x=\"172\" y=\"40\" width=\"134\" height=\"76\" rx=\"10\"/>\n<text class=\"fh\" x=\"239\" y=\"68\" text-anchor=\"middle\">RECORDED</text>\n<text class=\"ft\" x=\"239\" y=\"90\" text-anchor=\"middle\">one book, same day,</text>\n<text class=\"ft\" x=\"239\" y=\"106\" text-anchor=\"middle\">two signatures</text>\n<line class=\"arw\" x1=\"308\" y1=\"78\" x2=\"320\" y2=\"78\"/>\n<polygon class=\"head\" points=\"332,78 319,72 319,84\"/>\n<rect class=\"box\" x=\"334\" y=\"40\" width=\"134\" height=\"76\" rx=\"10\"/>\n<text class=\"fh\" x=\"401\" y=\"68\" text-anchor=\"middle\">OUT</text>\n<text class=\"ft\" x=\"401\" y=\"90\" text-anchor=\"middle\">rent, water, light,</text>\n<text class=\"ft\" x=\"401\" y=\"106\" text-anchor=\"middle\">every receipt kept</text>\n<line class=\"arw\" x1=\"470\" y1=\"78\" x2=\"482\" y2=\"78\"/>\n<polygon class=\"head\" points=\"494,78 481,72 481,84\"/>\n<rect class=\"box hi\" x=\"496\" y=\"40\" width=\"134\" height=\"76\" rx=\"10\"/>\n<text class=\"fh\" x=\"563\" y=\"68\" text-anchor=\"middle\">ANNOUNCED</text>\n<text class=\"ft\" x=\"563\" y=\"90\" text-anchor=\"middle\">read aloud,</text>\n<text class=\"ft\" x=\"563\" y=\"106\" text-anchor=\"middle\">once a month</text>\n<path class=\"arw\" d=\"M563 116 L563 174 L77 174 L77 130\"/>\n<polygon class=\"head\" points=\"77,118 70,131 84,131\"/>\n<text class=\"ft\" x=\"320\" y=\"200\" text-anchor=\"middle\">and the book stays open to anyone who asks, without being asked why</text>\n</svg>",
