"three-questions-rising-out-of-the-grav": "<svg viewBox=\"13.2 -2.8 453.7 324.7\" class=\"figsvg\" xmlns=\"http://www.w3.org/2000/svg\"><style>.figsvg .fl{fill:#FFFEF7;fill-opacity:0.96;font-size:15.5px;font-weight:600}\n.figsvg .fs{fill:#FFFEF7;fill-opacity:0.73;font-size:13.0px;font-weight:500}\n.figsvg .s1{fill:none;stroke:#E9C86A;stroke-width:2.87;stroke-linecap:round;stroke-linejoin:round}\n.figsvg .s3{fill:none;stroke:#F4D46A;stroke-opacity:0.496;stroke-width:1.77;stroke-linecap:round;stroke-linejoin:round}\n.figsvg .f1{fill:#F4D46A;fill-opacity:0.288}\n.figsvg .f2{fill:#F4D46A}</style>\n<circle class=\"f1\" cx=\"240\" cy=\"40\" r=\"26\"/><circle class=\"f2\" cx=\"240\" cy=\"40\" r=\"6\"/><circle class=\"s3\" cx=\"240\" cy=\"40\" r=\"36\"/><path class=\"s1\" d=\"M200 236 C142 202 96 162 92 120\"/><path class=\"s1\" d=\"M240 236 C266 190 254 148 240 106\"/><path class=\"s1\" d=\"M280 236 C338 202 384 162 388 120\"/><path class=\"s3\" d=\"M20 236H460\"/><rect class=\"s3\" x=\"170\" y=\"236\" width=\"140\" height=\"30\" rx=\"10\"/><text class=\"fs\" x=\"92\" y=\"104\" text-anchor=\"middle\">who is your Lord?</text><text class=\"fs\" x=\"240\" y=\"90\" text-anchor=\"middle\">what is your religion?</text><text class=\"fs\" x=\"388\" y=\"90\" text-anchor=\"middle\">what did you say</text><text class=\"fs\" x=\"388\" y=\"106\" text-anchor=\"middle\">about this man?</text><text class=\"fl\" x=\"240\" y=\"292\" text-anchor=\"middle\">the answer is not learned here</text><text class=\"fs\" x=\"240\" y=\"312\" text-anchor=\"middle\">it is the life, handed back to the one who lived it</text></svg>",
